insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_22_v1'
from (values
('127.149.d.1.A',3,'A mason spreads a mortar bed on a footing before laying the first course. The usual bed joint thickness is about:','["3/8 inch", "1/16 inch", "1 inch", "2 inches"]'::jsonb,0,'Standard mortar joints are 3/8 inch.','original'),
('127.149.d.1.A',4,'A mortar bed is spread with a trowel so that it is full and:','["Thin in the middle", "Even along the length of the bed", "Lumpy at the ends", "Wet and runny"]'::jsonb,1,'A uniform bed keeps units level.','original'),
('127.149.d.1.B',3,'When spreading mortar for a course at chest height, the mason should keep the mortar:','["On the scaffold edge", "Far from the wall", "Within reach so it does not dry out before units are set", "Spread for the whole day"]'::jsonb,2,'Spread only a few units ahead.','original'),
('127.149.d.1.B',4,'On a high lift, the mason spreads only a few feet of bed at a time mainly so the mortar:','["Freezes", "Dries solid", "Turns black", "Stays plastic and bonds"]'::jsonb,3,'Mortar that stiffens bonds poorly.','original'),
('127.149.d.1.C',3,'Spreading mortar for concrete block is different from brick because block is wider and often has:','["Face shell mortar bedding", "Mortar on the inside only", "Mortar on the top only", "No mortar at all"]'::jsonb,0,'CMU is bedded on the face shells.','original'),
('127.149.d.1.C',4,'A mason lays 8-inch CMU on face-shell bedding. Mortar is applied to the:','["Center web only", "Two long face shells", "Back of the unit only", "Entire inside cell"]'::jsonb,1,'Face shells carry the mortar.','original'),
('127.149.d.1.D',3,'The size of a trowel chosen for spreading mortar on large block is usually:','["The same always", "Smaller than for brick", "Larger than for brick", "A pointing tool"]'::jsonb,2,'Bigger units need more mortar.','original'),
('127.149.d.1.D',4,'Spreading mortar on a 12-inch block compared with a modular brick requires:','["No spreading", "A thinner bed than brick", "Only head joints", "A longer, heavier bed spread"]'::jsonb,3,'Block beds are longer.','original'),
('127.149.d.1.E',3,'Buttering a masonry unit means applying mortar to its:','["End or side before placing it", "Top face only", "Inside cells", "Back only"]'::jsonb,0,'Buttering forms the head joint.','original'),
('127.149.d.1.E',4,'A brick laid as a header needs buttering on the end that will:','["Stay dry", "Meet the next unit in the course", "Face the sky", "Face the ground"]'::jsonb,1,'The end forms the vertical joint.','original'),
('127.149.d.2.A',3,'A brick lead is built at the end of a wall to:','["Replace the footing", "Hold the scaffolding", "Guide the line for the courses between leads", "Mark the property"]'::jsonb,2,'Leads set the line and heights.','original'),
('127.149.d.2.A',4,'While building a lead, the mason checks each course with a level for plumb, level, and:','["Weight", "Moisture only", "Color match", "Alignment with the line"]'::jsonb,3,'Leads must be true.','original'),
('127.149.d.2.B',3,'To keep a brick wall straight between leads, the mason stretches a:','["Line", "Hose", "Fishing pole", "Rope ladder"]'::jsonb,0,'A mason''s line shows the face plane.','original'),
('127.149.d.2.B',4,'A level placed vertically on the wall face checks that the wall is:','["Colored", "Plumb", "Dry", "Cured"]'::jsonb,1,'Plumb means vertical.','original'),
('127.149.d.2.C',3,'An outside corner of a brick wall is a corner that:','["Is on the roof", "Turns into the building", "Projects outward from the building", "Is under the ground"]'::jsonb,2,'Outside corners stick out.','original'),
('127.149.d.2.C',4,'When building an outside corner, the mason checks the corner is plumb on:','["The top only", "Neither", "One face only", "Both faces"]'::jsonb,3,'Both faces must be plumb.','original'),
('127.149.d.2.D',3,'An inside corner is formed where two walls meet and form a corner that:','["Turns in toward the building", "Sticks out", "Is on the roof", "Is round"]'::jsonb,0,'Inside corners recess.','original'),
('127.149.d.2.D',4,'Which tool best checks that an inside corner is square?','["A trowel edge only", "A framing square or corner check", "A paintbrush", "A rubber band"]'::jsonb,1,'Squares verify 90 degrees.','original'),
('127.149.d.2.E',3,'A double wythe brick wall has:','["One layer only", "Four layers", "Two layers of brick separated by a collar joint", "No mortar"]'::jsonb,2,'Two wythes with a joint between them.','original'),
('127.149.d.2.E',4,'The space between two wythes is called the:','["Head joint", "Cap joint", "Footing", "Collar joint"]'::jsonb,3,'Collar joints sit between wythes.','original'),
('127.149.d.3.A',3,'A stretcher is a brick laid with its:','["Long narrow face exposed in the wall", "Short end exposed", "Bottom up", "Flat face up"]'::jsonb,0,'Stretchers show the long face.','original'),
('127.149.d.3.A',4,'In running bond, most of the bricks in the wall face are:','["Sailors", "Stretchers", "Headers", "Soldiers"]'::jsonb,1,'Running bond uses stretchers.','original'),
('127.149.d.3.B',3,'A header brick is laid with its:','["Standing on end", "Flat face up", "Short end exposed on the wall face", "Long face exposed"]'::jsonb,2,'Headers tie wythes together.','original'),
('127.149.d.3.B',4,'Header courses in a double wythe wall help:','["Save mortar", "Add color only", "Make the wall lighter", "Tie the two wythes together"]'::jsonb,3,'Headers cross the collar joint.','original'),
('127.149.d.3.C',3,'A rowlock brick is laid on its:','["Edge with the short end showing", "Long end", "Flat face", "Back"]'::jsonb,0,'Rowlocks are on edge.','original'),
('127.149.d.3.C',4,'A rowlock course is often found at a:','["Floor drain", "Sill or the top of a wall", "Door handle", "Footing only"]'::jsonb,1,'Rowlocks shed water.','original'),
('127.149.d.3.D',3,'A sailor is a brick laid:','["Flat on its bed", "On its long edge", "Standing on end with the broad face showing", "In a pile"]'::jsonb,2,'Sailors are on end, broad face out.','original'),
('127.149.d.3.D',4,'Which brick position stands on its end with the broad (bed) face out?','["Rowlock", "Stretcher", "Header", "Sailor"]'::jsonb,3,'Sailors have broad faces showing.','original'),
('127.149.d.3.E',3,'A soldier is a brick laid:','["Standing on end with the narrow face showing", "Flat", "On its long edge", "Sideways in a pile"]'::jsonb,0,'Soldiers stand on end.','original'),
('127.149.d.3.E',4,'A soldier course is often used above a door or window as a:','["Floor", "Decorative lintel course", "Footing", "Drain"]'::jsonb,1,'Soldier courses cap openings.','original'),
('127.149.d.3.F',3,'A shiner is also called a:','["Soldier", "Sailor", "Rowlock stretcher", "Corbel"]'::jsonb,2,'Another name for a shiner.','original'),
('127.149.d.3.F',4,'A shiner is laid with the brick resting on its:','["Flat bed", "Short end", "Top corner", "Long edge"]'::jsonb,3,'Shiners lie on their edge.','original'),
('127.149.d.4.A',3,'A column labeled 2 by 2 in brick has how many bricks in each course?','["Four", "One", "Eight", "Twelve"]'::jsonb,0,'A 2 by 2 column has four units per course.','original'),
('127.149.d.4.A',4,'The first thing a mason checks on a column is that each course is:','["Painted", "Level and plumb", "Weighed", "Colored"]'::jsonb,1,'Check every course.','original'),
('127.149.d.4.B',3,'A six-brick column is built with how many bricks per course?','["Two", "Ten", "Six", "Sixteen"]'::jsonb,2,'Count per course.','original'),
('127.149.d.4.B',4,'Alternating each course of a column so joints are not stacked is called:','["Painting", "Capping", "Frosting", "Bonding the courses"]'::jsonb,3,'Offset joints strengthen.','original'),
('127.149.d.4.C',3,'A column that is 2 bricks by 4 bricks has how many bricks per course?','["Eight", "Twelve", "Four", "Two"]'::jsonb,0,'2 x 4 = 8 per course.','original'),
('127.149.d.4.C',4,'A taller column is most likely to go out of plumb if the mason:','["Cleans tools", "Skips checking with a level", "Uses fresh mortar", "Wears gloves"]'::jsonb,1,'Check often.','original'),
('127.149.d.4.D',3,'A ten-brick column has how many bricks in each course?','["Sixteen", "Two", "Ten", "Six"]'::jsonb,2,'Ten per course.','original'),
('127.149.d.4.D',4,'Which course layout keeps vertical joints from lining up in a brick column?','["Using all headers", "Stacking each course the same", "Using no mortar", "Rotating the pattern every other course"]'::jsonb,3,'Alternate the pattern.','original'),
('127.149.d.5.A',3,'A CMU lead is built at the end of a block wall to:','["Set the line for the courses between leads", "Mark the grade", "Cool the mortar", "Replace the footing"]'::jsonb,0,'Leads guide the wall.','original'),
('127.149.d.5.A',4,'When laying a block lead, the first course is set in a full mortar bed and checked for:','["Texture", "Level and alignment", "Weight", "Color"]'::jsonb,1,'Foundation for the lead.','original'),
('127.149.d.5.B',3,'A block wall is checked with a level to ensure it is:','["Dry", "Colored", "Plumb and level", "Loud"]'::jsonb,2,'Level and plumb.','original'),
('127.149.d.5.B',4,'On a block wall, head joints are normally:','["1/8 inch thick", "3 inches thick", "1 inch thick", "3/8 inch thick"]'::jsonb,3,'Uniform joint thickness.','original'),
('127.149.d.5.C',3,'A block corner is built first so that the mason can:','["Run a line between the corners", "Skip the line", "Save mortar", "Avoid the level"]'::jsonb,0,'Corners set the line.','original'),
('127.149.d.5.C',4,'Corner block is used to:','["Reduce weight", "Finish the end of a wall with a flat face", "Cut cost", "Add color"]'::jsonb,1,'Special shapes.','original'),
('127.149.d.6.A',3,'A 2 by 2 column of 8-inch CMU is built with how many blocks in each course?','["Twelve", "Eight", "Four", "One"]'::jsonb,2,'2 x 2 = 4 blocks per course.','original'),
('127.149.d.6.A',4,'An 8-inch CMU nominally measures 8 by 8 by:','["12 inches", "24 inches", "8 inches", "16 inches"]'::jsonb,3,'Standard block size.','original'),
('127.149.d.6.B',3,'A six-block column is how many blocks tall if it has six courses?','["Six", "One", "Three", "Twelve"]'::jsonb,0,'One block per course in height.','original'),
('127.149.d.6.B',4,'Each course of 8-inch block is how tall including the joint?','["12 inches", "8 inches", "4 inches", "16 inches"]'::jsonb,1,'Nominal height 8.','original'),
('127.149.d.6.C',3,'A ten-course block column stands about how tall?','["160 inches", "40 inches", "80 inches", "100 inches"]'::jsonb,2,'10 x 8 = 80.','original'),
('127.149.d.6.C',4,'Ten courses of 8-inch block make a column nearly:','["4 feet", "12 feet", "10 feet", "6 feet 8 inches"]'::jsonb,3,'80 inches = 6 ft 8 in.','original'),
('127.149.d.6.D',3,'4-inch CMU is mostly used for:','["Partition or veneer backup walls", "Foundations", "Roads", "Heavy footings"]'::jsonb,0,'Thin block for light uses.','original'),
('127.149.d.6.D',4,'Compared with 8-inch block, 4-inch block is:','["The same", "Half as thick", "Twice as thick", "Heavier"]'::jsonb,1,'Nominal thickness 4 vs 8.','original'),
('127.149.d.6.E',3,'6-inch CMU has a nominal thickness of:','["10 inches", "4 inches", "6 inches", "8 inches"]'::jsonb,2,'Nominal thickness.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
