       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_22_v1'
from (values
('127.149.d.6.E',4,'A 6-inch block is thicker than 4-inch block and thinner than:','["Floor tile", "2-inch block", "Brick veneer", "8-inch block"]'::jsonb,3,'Size order.','original'),
('127.149.d.7.A',3,'A composite wall of brick and block combines two:','["Different masonry materials", "Doors", "Floors", "Roofs"]'::jsonb,0,'Composite means combined.','original'),
('127.149.d.7.A',4,'In a composite wall, metal ties join the brick to the block backup to:','["Reduce mortar", "Help them act together", "Add color", "Add weight"]'::jsonb,1,'Ties connect the wythes.','original'),
('127.149.d.7.B',3,'In a brick and 4-inch block wall, the block wythe is the:','["Cap", "Footing", "Backup", "Facing"]'::jsonb,2,'Block backs up brick.','original'),
('127.149.d.7.B',4,'The collar joint of a composite wall is filled with mortar or left as:','["A roof", "A door", "A paint coat", "An air space"]'::jsonb,3,'Cavity design.','original'),
('127.149.d.8.A',3,'Coping is placed on top of a masonry wall to:','["Shed water and protect the wall", "Hold scaffolding", "Mark the wall", "Decorate the footing"]'::jsonb,0,'Copings cap walls.','original'),
('127.149.d.8.A',4,'A single brick rowlock coping uses bricks laid:','["Flat on the face", "On edge across the wall top", "Standing on end", "In the footing"]'::jsonb,1,'Rowlock coping.','original'),
('127.149.d.8.B',3,'A double brick rowlock coping has how many rows across the wall width?','["Six", "Four", "Two", "One"]'::jsonb,2,'Double equals two.','original'),
('127.149.d.8.B',4,'Double rowlock coping is used on a wall about how thick?','["40 inches", "2 inches", "24 inches", "8 inches"]'::jsonb,3,'Two rowlocks cover about 8 inches.','original'),
('127.149.d.8.C',3,'A 12-inch bonded brick rowlock coping covers a wall:','["12 inches wide", "1 inch wide", "4 inches wide", "12 feet wide"]'::jsonb,0,'Width matches the coping.','original'),
('127.149.d.8.C',4,'Bonded coping bricks are laid with joints that are:','["Left open", "Offset like other bonded courses", "Aligned in a stack", "Dry"]'::jsonb,1,'Bonding gives strength.','original'),
('127.149.d.8.D',3,'A 16-inch bonded rowlock coping is used on a wall:','["With no width", "Under the floor", "Wider than a 12-inch wall", "Narrower than 4 inches"]'::jsonb,2,'Larger width.','original'),
('127.149.d.8.D',4,'Coping should slope slightly to:','["Hide mortar", "Pool water", "Hold dirt", "Drain water away from the wall"]'::jsonb,3,'Slope sheds water.','original'),
('127.149.d.8.E',3,'Limestone coping is a type of:','["Natural stone cap", "Plastic strip", "Rubber pad", "Painted wood"]'::jsonb,0,'Limestone is natural.','original'),
('127.149.d.8.E',4,'Limestone coping pieces are set with a mortar bed and:','["Open joints", "Sealed joints to keep water out", "No joints", "Painted edges only"]'::jsonb,1,'Water protection.','original'),
('127.149.d.8.F',3,'Cast stone is made by:','["Cutting plastic", "Weaving fibers", "Casting concrete mixed with fine aggregates in molds", "Carving granite"]'::jsonb,2,'Cast stone imitates natural stone.','original'),
('127.149.d.8.F',4,'Cast stone coping is chosen because it is:','["Made of metal", "Always random", "Free of cost", "Consistent in color and shape"]'::jsonb,3,'Manufactured consistency.','original'),
('127.149.d.8.G',3,'Prefab concrete coping is delivered to the site:','["Precast in standard lengths", "As powder only", "As bricks", "As liquid"]'::jsonb,0,'Prefab means pre-made.','original'),
('127.149.d.8.G',4,'The joints between prefab coping pieces should be:','["Painted over", "Sealed with an appropriate sealant", "Filled with sand only", "Left open"]'::jsonb,1,'Watertight.','original'),
('127.149.d.9.A',3,'Setting natural stone in a random pattern means the pieces are placed:','["In straight perfect rows", "In a repeating grid", "Without a regular course lines", "Only vertically"]'::jsonb,2,'Random is irregular.','original'),
('127.149.d.9.A',4,'When setting random stone, each stone should be seated on:','["Tape", "Loose gravel", "Dry sand", "A full bed of mortar"]'::jsonb,3,'Bedding gives stability.','original'),
('127.149.d.9.B',3,'An ashlar pattern uses stone cut into:','["Rectangular pieces laid in courses", "Round balls", "Random chunks", "Triangular only"]'::jsonb,0,'Ashlar is squared stone.','original'),
('127.149.d.9.B',4,'Ashlar can be coursed or random-coursed. The stones always have:','["Jagged breaks", "Squared faces and edges", "No shape", "Round corners"]'::jsonb,1,'Ashlar is dressed stone.','original'),
('127.149.d.9.C',3,'Flat work of natural stone is used for items such as:','["Wall footings", "Roofs", "Patios and walkways", "Chimney flues"]'::jsonb,2,'Flat work is horizontal.','original'),
('127.149.d.9.C',4,'Flagstone for flat work is commonly laid in a random pattern over a:','["Open air", "Wall", "Wet sand only", "Prepared base"]'::jsonb,3,'Base prep.','original'),
('127.149.d.10.A',3,'Manufactured stone is made from:','["Concrete shaped and colored to look like stone", "Wood", "Plastic only", "Real granite"]'::jsonb,0,'Man-made veneer.','original'),
('127.149.d.10.A',4,'Manufactured stone veneer is installed over a surface prepared with:','["Sand", "A scratch coat and lath where required", "Wet paint", "Bare plastic"]'::jsonb,1,'Substrate prep.','original'),
('127.149.d.10.B',3,'When installing manufactured stone in an ashlar pattern, the pieces are laid in:','["Random angles", "Vertical stacks", "Level horizontal courses", "Circles"]'::jsonb,2,'Ashlar is coursed.','original'),
('127.149.d.10.B',4,'A mason cuts manufactured stone with a:','["Pencil", "Spoon", "Paint brush", "Masonry saw or hammer and chisel"]'::jsonb,3,'Cutting tools.','original'),
('127.149.d.11.A',3,'Modular brick has a nominal size of:','["4 by 2-2/3 by 8 inches", "1 by 1 by 1 inch", "12 by 12 by 12 inches", "16 by 16 by 8 inches"]'::jsonb,0,'Standard modular unit.','original'),
('127.149.d.11.A',4,'Three courses of modular brick with joints equal how many inches of wall height?','["24 inches", "8 inches", "12 inches", "3 inches"]'::jsonb,1,'Modular coursing 3 = 8.','original'),
('127.149.d.11.B',3,'King-size brick compared with modular brick is generally:','["Shorter", "Smaller overall", "Longer", "Square"]'::jsonb,2,'Larger unit.','original'),
('127.149.d.11.B',4,'A mason laying king-size brick to a line adjusts the course height because the brick is:','["Painted", "Heavy", "Bigger on the ceiling", "A different height than modular"]'::jsonb,3,'Modular rules change.','original'),
('127.149.d.11.C',3,'Queen-size brick is similar to king-size brick but typically:','["A bit narrower in height", "Wider by double", "Made of metal", "Round"]'::jsonb,0,'Different dimension.','original'),
('127.149.d.11.C',4,'Queen brick used with a line needs course heights checked with a:','["Thermometer", "Story pole or gauge", "Paint chart", "Calendar"]'::jsonb,1,'Gauge keeps coursing.','original'),
('127.149.d.11.D',3,'Utility brick measures nominally:','["1 by 1 by 1 inch", "2 by 2 by 4 inches", "4 by 4 by 12 inches", "8 by 8 by 8 inches"]'::jsonb,2,'Utility is large.','original'),
('127.149.d.11.D',4,'Because utility brick is taller, one course gains height of:','["1 inch", "16 inches", "12 inches", "4 inches nominally"]'::jsonb,3,'Utility course = 4 in.','original'),
('127.149.d.12.A',3,'When laying 8-inch CMU to a line, the top outside edge of each block touches the:','["Line without pushing it", "Ladder", "Roof", "Floor"]'::jsonb,0,'Line gauges position.','original'),
('127.149.d.12.A',4,'The mason uses a level along the block course to check it is:','["Wet", "Level and in the same plane", "Dirty", "New"]'::jsonb,1,'Alignment.','original'),
('127.149.d.12.B',3,'4-inch CMU laid to a line must be handled with care because it is:','["Made of steel", "Thicker than brick", "Thinner and more fragile than 8-inch", "Always solid"]'::jsonb,2,'Thin units crack easily.','original'),
('127.149.d.12.B',4,'A 4-inch block wall without lateral support can be:','["Very strong", "Fireproof only", "Waterproof only", "Unstable at height"]'::jsonb,3,'Needs bracing.','original'),
('127.149.d.12.C',3,'6-inch CMU laid to a line is often used for:','["Interior walls", "Footings", "Bridge decks", "Roads"]'::jsonb,0,'Mid-size block.','original'),
('127.149.d.12.C',4,'Compared with 8-inch block, a 6-inch wall uses:','["The same", "Less material per square foot", "No block", "More material"]'::jsonb,1,'Thinner wall.','original'),
('127.149.d.12.D',3,'12-inch CMU is chosen for walls that need:','["Lower cost only", "Less weight only", "More thickness and strength", "Color only"]'::jsonb,2,'Heavy-duty block.','original'),
('127.149.d.12.D',4,'Because 12-inch block is heavy, masons often use:','["Water balloons", "Rope ladders", "Their teeth", "Two people or lifting aids"]'::jsonb,3,'Safe lifting.','original'),
('127.150.d.2',3,'A mason finds a wall racked out of line. A strong problem-solving first step is to:','["Check the line and level to find the cause", "Remove the line", "Ignore it", "Add paint"]'::jsonb,0,'Diagnose before fixing.','original'),
('127.150.d.2',4,'Critical thinking on a masonry site means weighing options before deciding. When mortar sets too fast in hot weather, a good decision is to:','["Let it harden fully", "Mix smaller batches and keep the mortar tempered", "Use it as is", "Add dry cement"]'::jsonb,1,'Adjust to conditions.','original'),
('127.150.d.1.A',3,'On a masonry job, clear spoken communication prevents:','["Pay", "Mortar", "Mistakes in layout and coursing", "Weather"]'::jsonb,2,'Communicate clearly.','original'),
('127.150.d.1.A',4,'When a lead mason says "check your line," the helper should:','["Move the level", "Ignore it", "Leave", "Confirm the line is tight and in place"]'::jsonb,3,'Respond to directions.','original'),
('127.150.d.1.B',3,'A bricklayer who winces while watching a helper lift a block may be signaling:','["A concern about technique", "Boredom", "Nothing", "Delight"]'::jsonb,0,'Read cues.','original'),
('127.150.d.1.B',4,'A foreman''s silence while looking at your joints may mean:','["Lunch is ready", "They want you to check the work", "The work is perfect", "They love it"]'::jsonb,1,'Interpret cues.','original'),
('127.150.d.1.C',3,'Active listening on a masonry crew includes:','["Interrupting", "Walking away", "Repeating the instructions to confirm", "Texting"]'::jsonb,2,'Confirm.','original'),
('127.150.d.1.C',4,'Before building a corner, the mason asks the foreman a question about the plan to:','["Delay lunch", "Avoid work", "Waste time", "Clarify the layout"]'::jsonb,3,'Questions help.','original'),
('127.150.d.3.A',3,'Masonry workers should wear safety glasses because chipped brick and block create:','["Flying fragments", "Extra light", "Sound", "Cold air"]'::jsonb,0,'Eye protection.','original'),
('127.150.d.3.A',4,'Silica dust from cutting masonry is controlled with wet cutting or a:','["Paint", "Dust collection system and respirator", "Fan blowing it around", "Open flame"]'::jsonb,1,'Protect lungs.','original')
